import Phaser from 'phaser'
import { ART_ASSETS, spiderBodySource, svgDataUri } from '../visual/art.js'

// Vite checks the local manifest and files at startup/build. No absent-resource probes.
export default class PreloadScene extends Phaser.Scene {
  constructor() { super('PreloadScene') }
  preload() {
    for (const { key, file, width, height } of ART_ASSETS) {
      this.load.svg(key, `${import.meta.env.BASE_URL}art2d/${file}`, { width, height })
    }
    // Keep the full SVG texture available while extracting only its body for gait frames.
    this.load.text('art2d-karakurt-source', `${import.meta.env.BASE_URL}art2d/karakurt.svg`)
    this.load.once('filecomplete-text-art2d-karakurt-source', (_key, _type, source) => {
      const body = spiderBodySource(source)
      if (body) this.load.svg('art2d-karakurt-body', svgDataUri(body), { width: 256, height: 256 })
    })
    for (const { actor, state, file } of __JAM2D_ASSETS__) {
      this.load.spritesheet(`jam-${actor}-${state}`, `${import.meta.env.BASE_URL}assets/jam2d/${file}`, { frameWidth: 512, frameHeight: 512 })
    }
    this.load.on('loaderror', file => console.warn(`Необязательный ассет ${file.key}: используется процедурный fallback`))
  }
  create() { this.scene.start('MenuScene') }
}
